CREATE OR REPLACE FUNCTION chk_k14() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
  IF (NEW.c2 IS NOT NULL AND NEW.c5 IS NOT NULL) AND (EXISTS (SELECT 1 FROM T WHERE (c2 IS NOT NULL AND c5 IS NOT NULL AND c1=NEW.c1 AND c2=NEW.c2 AND c5=NEW.c5) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid)) OR EXISTS (SELECT 1 FROM T WHERE (c2 IS NULL AND c5 IS NOT NULL AND c1=NEW.c1 AND c5=NEW.c5) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid)) OR EXISTS (SELECT 1 FROM T WHERE (c5 IS NULL AND c2 IS NOT NULL AND c1=NEW.c1 AND c2=NEW.c2) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid)) OR EXISTS (SELECT 1 FROM T WHERE (c2 IS NULL AND c5 IS NULL AND c1=NEW.c1) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid))) THEN RAISE EXCEPTION 'partial key k14 violated'; END IF;
  IF (NEW.c2 IS NULL AND NEW.c5 IS NOT NULL) AND (EXISTS (SELECT 1 FROM T WHERE (c2 IS NOT NULL AND c5 IS NOT NULL AND c1=NEW.c1 AND c5=NEW.c5) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid)) OR EXISTS (SELECT 1 FROM T WHERE (c2 IS NULL AND c5 IS NOT NULL AND c1=NEW.c1 AND c5=NEW.c5) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid)) OR EXISTS (SELECT 1 FROM T WHERE (c2 IS NULL AND c5 IS NULL AND c1=NEW.c1) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid))) THEN RAISE EXCEPTION 'partial key k14 violated'; END IF;
  IF (NEW.c5 IS NULL AND NEW.c2 IS NOT NULL) AND (EXISTS (SELECT 1 FROM T WHERE (c2 IS NOT NULL AND c5 IS NOT NULL AND c1=NEW.c1 AND c2=NEW.c2) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid)) OR EXISTS (SELECT 1 FROM T WHERE (c5 IS NULL AND c2 IS NOT NULL AND c1=NEW.c1 AND c2=NEW.c2) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid)) OR EXISTS (SELECT 1 FROM T WHERE (c2 IS NULL AND c5 IS NULL AND c1=NEW.c1) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid))) THEN RAISE EXCEPTION 'partial key k14 violated'; END IF;
  IF (NEW.c2 IS NULL AND NEW.c5 IS NULL) AND (EXISTS (SELECT 1 FROM T WHERE (c2 IS NOT NULL AND c5 IS NOT NULL AND c1=NEW.c1) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid)) OR EXISTS (SELECT 1 FROM T WHERE (c2 IS NULL AND c5 IS NOT NULL AND c1=NEW.c1) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid)) OR EXISTS (SELECT 1 FROM T WHERE (c5 IS NULL AND c2 IS NOT NULL AND c1=NEW.c1) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid)) OR EXISTS (SELECT 1 FROM T WHERE (c2 IS NULL AND c5 IS NULL AND c1=NEW.c1) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid))) THEN RAISE EXCEPTION 'partial key k14 violated'; END IF;
  RETURN NEW; END $$;
CREATE TRIGGER trg_k14 BEFORE INSERT OR UPDATE ON T FOR EACH ROW EXECUTE FUNCTION chk_k14();
CREATE UNIQUE INDEX k15 ON T(c0,c7);
